package test;
import org.eclipse.jface.preference.IPreferenceStore;
import org.eclipse.jdt.ui.PreferenceConstants;

public class MyPlugin {
    public void initializeDefaults(IPreferenceStore store) {
        store.setDefault(PreferenceConstants.PREF_MAX_CHAINS, 20); // Different constant
        store.setDefault(PreferenceConstants.PREF_CHAIN_TIMEOUT, 5); // Different value
        store.setValue(PreferenceConstants.PREF_CHAIN_TIMEOUT, 3); // Different method
    }
}
